  Variable LSt : lib_statics.
  Hypothesis DLL : drv_lib_layoutA Lay L.
  Variables PayOk PayExport : list byte -> Prop.      (* [comment removed for export] *)
  Hypothesis LIokX : lib_call_okA_x Lay ar scfg HI LSt PayOk PayExport.

  #[local] Notation dinvA := (dinv ar HI sp0 M0).
  #[local] Notation LV := (lib_view Lay ar).

